1	// Tập 7 · C4 · ĐOẠN G = S29–S33. Leo (ILLUSTRATIVE, màu riêng, BÊN TRÁI Tessa) mọc cùng nhà; chồng của Leo thấp, hộp cushion rộng, thanh thấp — cạnh cụm
2	// của Tessa (chồng cao, thanh cao) → ô thứ ba trống (thanh trống, chồng trống: "your bar", "your stack") → thẻ phương pháp V7 → khung cold open: hai thẻ
3	// khoản vay trượt vào nhau thành "30-year paid in 15 = 15-year + a fallback", "week of Oct 8, 2026: $120 a month". Mốc giờ chỉ từ spine.json.
4	import { setup, figure, gesture, figTag, OfferCard, theStack, stackSet, BUNDLE_TH, modeLook, followLight, chrome, label, seg2, dip, CHAR,
5	  kf, show, pulse, C, ease, lin, mix, THREE, setOpacity } from '/episodes/ep007/world/c4kit.js';
6	import { Beam } from '/toolkit/factory/world/lib3d.js';
7	
8	const SEG = '/episodes/ep007/world/c4/g-s29-s33/';
9	const PER_PCT = 0.3, GAP_U = 1 / 500;   // thanh: 0,3/điểm % (như S25); hộp cushion: 1/500 đơn vị mỗi $/tháng của khoảng chênh khoản trả
10	
11	export async function boot(res) {
12	  const poses = {
13	    wPair0: { pos: [-3.0, 3.2, 11.5], tgt: [-1.4, 1.1, 0], fov: 44, chart: 0 },
14	    cPair: { pos: [-2.0, 1.7, 19.14], tgt: [-2.0, 1.7, 0], fov: 20, chart: 1 },
15	    cThree: { pos: [-0.4, 1.9, 24.24], tgt: [-0.4, 1.9, 0], fov: 20, chart: 1 },
16	    wHome: { pos: [-2.2, 2.7, 8.6], tgt: [1.7, 0.9, 0], fov: 40, chart: 0 },
17	    cHome: { pos: [1.2, 2.2, 16.93], tgt: [1.2, 2.2, 0], fov: 22, chart: 1 },
18	  };
19	  const { S, D, G, cue, MV, st, O, renderer, scene, floor, key, CAM } = await setup(SEG, res, poses);
20	  const b = cue, X = S.x;
21	  const hm = figure(scene, { x: X.house }), leo = figure(scene, { x: X.leo_house, color: CHAR.leo, char: 'Leo' });
22	  const tStack = theStack(scene, G, { x: X.stack }), lStack = theStack(scene, G, { x: X.leo_stack });
